#!/usr/bin/env python3
"""M017 public-canary inference (regenerated bytes, committed models only).

- Regenerates the canary cohort + typed dataset deterministically and
  asserts the frozen cohort SHA (fail-closed on drift).
- Runs `experiment evaluate` for typed-choice-tinymlp on every host
  (committed fixture artifact) and, on hosts with M016 baseline outputs,
  for the three legacy heads.
- Writes a per-host attestation (decisions + probabilities + SHAs) for the
  cross-host parity job. The canary is public and NEVER the final cohort;
  no gate or selection consumes canary metrics.
"""
import argparse
import hashlib
import json
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(Path(__file__).parent))
import generate_m017_suite  # noqa: E402
import materialize_m017  # noqa: E402

TINYMLP_ARCH = "typed-choice-tinymlp"
TINYMLP_ENVELOPE = "sdm-typed-choice-tinymlp-v1"
LEGACY = ("typed-choice", "typed-choice-cross", "typed-choice-compositional")
LEGACY_ENVELOPES = {
    "typed-choice": "sdm-typed-task-v1",
    "typed-choice-cross": "sdm-typed-choice-cross-v1",
    "typed-choice-compositional": "sdm-typed-choice-compositional-v1",
}


def sha_file(path):
    return "sha256:" + hashlib.sha256(Path(path).read_bytes()).hexdigest()


def atomic_write(path, payload: bytes):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        if hashlib.sha256(path.read_bytes()).hexdigest() == hashlib.sha256(payload).hexdigest():
            return
        raise FileExistsError(f"refusing to overwrite different canary output: {path}")
    fd, tmp = tempfile.mkstemp(prefix=path.name + ".", dir=str(path.parent))
    try:
        import os

        with open(fd, "wb") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        json.loads(payload)
        os.replace(tmp, path)
    finally:
        import os as _os

        if _os.path.exists(tmp):
            _os.unlink(tmp)


def run_cargo(args):
    proc = subprocess.run(args, cwd=ROOT, capture_output=True, text=True)
    if proc.returncode:
        raise RuntimeError(f"{' '.join(args[-4:])} failed: {proc.stderr.strip()[-2000:]}")
    return proc.stdout


def evaluate_once(arch, envelope_arch, artifact, dataset, split, out_manifest,
                  protocol_sha, freeze_sha):
    bundle = json.loads(Path(dataset).read_text())
    split_doc = json.loads(Path(split).read_text())
    env = json.loads(Path(artifact).read_text())
    test_ids = sorted(split_doc["test"])
    mem_sha = "sha256:" + hashlib.sha256(
        json.dumps(test_ids, separators=(",", ":")).encode()).hexdigest()
    spec = {
        "dataset_path": str(dataset), "split_path": str(split),
        "artifact_path": str(artifact),
        "report_path": str(Path(out_manifest).with_suffix(".report-w.json")),
        "expected_artifact_sha256": sha_file(artifact),
        "expected_dataset_sha256": split_doc["dataset_sha256"],
        "expected_split_fingerprint": split_doc["fingerprint"],
        "expected_test_membership_sha256": mem_sha,
        "expected_architecture": arch,
        "expected_artifact_architecture": envelope_arch,
        "expected_feature_schema_sha256": env["required_feature_schema_sha256"],
        "expected_calibration_sha256": env["calibration_sha256"],
        "protocol_sha256": protocol_sha,
        "freeze_sha256": freeze_sha,
        "provenance": bundle["provenance"],
    }
    spec_path = Path(out_manifest).with_suffix(".spec.json")
    atomic_write(spec_path, (json.dumps(spec, indent=2) + "\n").encode())
    stdout = run_cargo(["cargo", "run", "-q", "-p", "sdm-experiment", "--locked",
                        "--", "experiment", "evaluate", "--config", str(spec_path)])
    manifest = json.loads(stdout)
    assert manifest["evaluated_partition"] == "test"
    assert manifest["test_evaluation_performed"] is True
    atomic_write(out_manifest, (json.dumps(manifest, indent=2, sort_keys=True) + "\n").encode())
    return manifest


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", type=Path, required=True)
    ap.add_argument("--workdir", type=Path, default=ROOT / "target/m017-canary")
    ap.add_argument("--binding", type=Path, default=ROOT / "docs/m017-binding-v1.json")
    ap.add_argument("--tinymlp-artifact", type=Path,
                    default=ROOT / "fixtures/m016-tinymlp-selected.artifact.json")
    ap.add_argument("--legacy-dir", type=Path, default=ROOT / "target/m016/baselines",
                    help="M016 baseline artifacts (linux-x64 only; skipped elsewhere)")
    ap.add_argument("--platform", required=True,
                    choices=("linux-x86_64", "linux-aarch64", "macos-aarch64"))
    args = ap.parse_args()
    out = Path(args.out)
    workdir = Path(args.workdir)
    workdir.mkdir(parents=True, exist_ok=True)

    binding = json.loads(args.binding.read_text())
    prelim_sha = binding["preliminary_sha256"]
    prelim = json.loads((ROOT / "docs/m017-preliminary-v1.json").read_text())
    expected_cohort_sha = prelim["cohorts"]["canary"]["output_sha256"]

    manifest = generate_m017_suite.generate(workdir, "canary")
    assert manifest["output_sha256"] == expected_cohort_sha, \
        f"canary drift: {manifest['output_sha256']} != {expected_cohort_sha}"
    dataset, split, _ = materialize_m017.materialize(
        workdir / "canary.jsonl", workdir / "typed")
    protocol_sha = sha_file(ROOT / "docs/m017-protocol-v1.json")

    evaluated = {}
    tiny = evaluate_once(TINYMLP_ARCH, TINYMLP_ENVELOPE, args.tinymlp_artifact,
                         dataset, split, workdir / "tinymlp.evaluate.json",
                         protocol_sha, prelim_sha)
    evaluated[TINYMLP_ARCH] = tiny["artifact_sha256"]
    for arch in LEGACY:
        art = args.legacy_dir / f"{arch}.artifact.json"
        if not art.exists():
            continue
        m = evaluate_once(arch, LEGACY_ENVELOPES[arch], art, dataset, split,
                          workdir / f"{arch}.evaluate.json", protocol_sha, prelim_sha)
        evaluated[arch] = m["artifact_sha256"]

    tiny_outcomes = [
        {"case_id": o["case_id"], "predicted": o["prediction"],
         "probs": o["raw_probabilities"],
         "answerability": o["answerability_probability"]}
        for o in tiny["outcomes"]
    ]
    decisions_sha = "sha256:" + hashlib.sha256(
        json.dumps(tiny_outcomes, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    attestation = {
        "schema": "sdm-m017-canary-attestation-v1",
        "platform": args.platform,
        "cohort_output_sha256": expected_cohort_sha,
        "test_membership_sha256": tiny["test_membership_sha256"],
        "tinymlp_artifact_sha256": tiny["artifact_sha256"],
        "evaluated": evaluated,
        "tinymlp_outcomes": tiny_outcomes,
        "decisions_sha256": decisions_sha,
        "source_commit": subprocess.run(
            ["git", "rev-parse", "HEAD"], capture_output=True, text=True,
            cwd=ROOT).stdout.strip(),
    }
    atomic_write(out, (json.dumps(attestation, indent=2, sort_keys=True) + "\n").encode())
    print(json.dumps({"platform": args.platform, "evaluated": evaluated,
                      "decisions_sha256": decisions_sha}, indent=2))


if __name__ == "__main__":
    main()
